message.content:
{
  "avaliacoes": [
    {
      "criterio": "aderencia_curricular",
      "nota": 1,
      "justificativa": "O plano limita-se a identificar e explicar listas, sem que os alunos criem soluções programáticas nem utilizem recursão, que são requisitos centrais da habilidade EF08CO02."
    },
    {
      "criterio": "alinhamento_objetivos",
      "nota": 2,
      "justificativa": "Os objetivos OBJ1 e OBJ2 são observáveis, porém focam apenas em identificação e explicação, não contemplam a criação de soluções com listas, gerando desalinhamento parcial com a habilidade."
    },
    {
      "criterio": "coerencia_metodologica",
      "nota": 3,
      "justificativa": "A metodologia de exposição dialogada está refletida nas etapas ET1 e ET2; a sequência de abertura, demonstração e discussão segue lógica coerente e respeita o tipo de aula teórica."
    },
    {
      "criterio": "viabilidade",
      "nota": 3,
      "justificativa": "Os recursos (quadro, pincel, projetor) e os tempos (25 min + 25 min) são adequados e realistas para as atividades descritas."
    },
    {
      "criterio": "avaliacao_aprendizagem",
      "nota": 2,
      "justificativa": "As evidências EVI1 e EVI2 são observáveis, porém os critérios de avaliação são genéricos e não discriminam níveis de desempenho (ex.: adequado vs inadequado)."
    },
    {
      "criterio": "inclusao",
      "nota": 3,
      "justificativa": "As adaptações ADP1 e ADP2 oferecem alternativas concretas (analogias, destaque de trechos) que mantêm os objetivos e utilizam os mesmos recursos."
    }
  ],
  "falhas": [
    {
      "id": "F1",
      "criterio": "aderencia_curricular",
      "componente": "sequencia",
      "gravidade": "critica",
      "descricao": "Nenhuma atividade exige que os alunos criem ou programem uma solução usando listas ou recursão, contrariando a exigência da habilidade EF08CO02.",
      "correcao_sugerida": "Inserir uma etapa prática em que os alunos, individualmente ou em pares, desenvolvam um pequeno algoritmo que utilize listas (ex.: somar elementos de uma lista) e, opcionalmente, implementem recursão para o caso base."
    },
    {
      "id": "F2",
      "criterio": "alinhamento_objetivos",
      "componente": "objetivos",
      "gravidade": "maior",
      "descricao": "Os objetivos OBJ1 e OBJ2 não contemplam a criação de soluções programáticas, limitando-se a identificação e explicação.",
      "correcao_sugerida": "Reformular os objetivos para incluir, por exemplo: \"Desenvolver um algoritmo simples que utilize listas para resolver um problema proposto\" e \"Implementar, com ou sem recursão, a solução em linguagem de programação\"."
    },
    {
      "id": "F3",
      "criterio": "avaliacao_aprendizagem",
      "componente": "avaliacao_preliminar",
      "gravidade": "maior",
      "descricao": "Os critérios de avaliação (participar, demonstrar compreensão) são genéricos e não especificam indicadores de desempenho nem níveis de proficiência.",
      "correcao_sugerida": "Definir rubricas com descritores claros (ex.: nível 1 – resposta incompleta; nível 2 – resposta correta com explicação parcial; nível 3 – resposta completa e correta) para as evidências EVI1 e EVI2."
    }
  ],
  "resumo": "O plano apresenta boa coerência metodológica, viabilidade e inclusão, mas falha em aderir à habilidade ao não envolver criação de soluções com listas/recursão, apresenta objetivos parcialmente desalinhados e avaliação pouco discriminativa."
}

